mapper.select:
SELECT v.id, v.shop_id, v.title, v.sub_title, v.rules, v.pay_value, v.actual_value, v.type, v.status, s.name AS shop_name, sv.stock, sv.begin_time, sv.end_time FROM tb_voucher v INNER JOIN tb_shop s ON s.id = v.shop_id LEFT JOIN tb_seckill_voucher sv ON sv.voucher_id = v.id WHERE v.status = 1 AND s.type_id = #{typeId} AND v.shop_id = #{shopId}
AND (s.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR v.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR v.sub_title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!')
ORDER BY v.id DESC LIMIT #{size} OFFSET #{offset}
